    padding: 0 15px;
}
.regex_script_name { white-space: normal; }

/* 快速切换 user */
#quickPersonaCaret { display: none !important; }
#quickPersonaMenu ul {
    background: rgba(9, 12, 18, 0.96) !important;
    border: 1px solid color-mix(in srgb, var(--冰蓝), transparent 78%) !important;
    box-shadow: none !important;
}
#quickPersonaMenu li { width: 45px !important; height: 45px !important; }

/* 输入助手 */
.integrated-button-row { background: none !important; }

/* 欢迎页 */
.welcomePanel { background: none !important; }
.welcomePanel .recentChatList .recentChat {
    margin: 4px 0;
    background: rgba(255, 255, 255, 0.04) !important;
    border: 1px solid color-mix(in srgb, var(--冰蓝), transparent 82%) !important;
    border-radius: 2px !important;
    box-shadow: none !important;
}

/* --- 加载动画：冰层下的呼吸 --- */
#load-spinner {
    animation: breathPulse 1.8s infinite ease-in-out !important;
}
#load-spinner::before {
    color: transparent !important;
    font-size: 70px;
    background:
        radial-gradient(circle at 34% 42%,
            color-mix(in srgb, var(--冰蓝), transparent 10%) 0 5px, transparent 11px),
        radial-gradient(circle at 62% 28%,
            color-mix(in srgb, var(--冰蓝), transparent 40%) 0 4px, transparent 9px),
        radial-gradient(circle at 70% 62%,
            color-mix(in srgb, var(--朱砂), transparent 30%) 0 3px, transparent 8px),
        radial-gradient(circle at 44% 70%,
            color-mix(in srgb, var(--冰蓝), transparent 60%) 0 2.5px, transparent 7px);
    background-repeat: no-repeat;
}
@keyframes breathPulse {
    0%, 100% { opacity: 0.35; transform: scale(0.92); }
    50% { opacity: 1; transform: scale(1.06); }
}

/* 手机窄屏微调 */
@media screen and (max-width: 420px) {
    .mes::before { font-size: 11px; letter-spacing: 5px; }
    .mes .ch_name::after { font-size: 9.5px; }
    .mes .swipe_right { left: 82px; }
    .mes .swipes-counter { left: 150px; }
}

